const raw = ($json.body?.message || '').toLowerCase();
const name = raw.replace(/^(analisa|cek|pokemon|pokédex|pokedex|stats|info)\s*/i, '').replace(/^["']|["']$/g, '').replace(/#\d+/g, '').trim() || 'pikachu';
return { json: { name, pokeUrl: `https://pokeapi.co/api/v2/pokemon/${encodeURIComponent(name)}` } };

const p = $json;
const types = (p.types || []).map(t => t.type.name).join(' / ');
const stats = {};
(p.stats || []).forEach(s => { stats[s.stat.name] = s.base_stat; });

let content = `🔴⚪ **[POKÉDEX: #${p.id} ${p.name.toUpperCase()}]**\n\n`;
content += `- **Tipe:** **${types}**\n`;
content += `- **Ukuran:** 📏 **${(p.height/10).toFixed(1)} m** / ⚖️ **${(p.weight/10).toFixed(1)} kg**\n\n`;
content += `### ⚔️ Base Stats:\n`;
content += `- **HP:** ${stats.hp || 0} | **Attack:** ${stats.attack || 0} | **Defense:** ${stats.defense || 0}\n`;
content += `- **Sp. Atk:** ${stats['special-attack'] || 0} | **Sp. Def:** ${stats['special-defense'] || 0} | **Speed:** ${stats.speed || 0}\n\n`;

const sprite = p.sprites?.other?.['official-artwork']?.front_default || p.sprites?.front_default;
if (sprite) content += `🖼️ **Artwork:** [Lihat Sprite Resmi](${sprite})\n`;

const chips = ['⚡ Analisa "Pikachu"', '🔥 Analisa "Charizard"', '💧 Analisa "Greninja"', '🔮 Analisa "Mewtwo"'];
return { json: { content, chips } };
